/**
 * The emails of the client (release B1a): the registration code (ours, generated by the
 * server) and the code of the return (Supabase's, from generateLink without sending). Plain
 * text and HTML with the logo, never a link: the code is typed on the page the client has
 * open. Pure: tested in tests/percorso-testi.test.ts, sent by lib/email/invia.ts.
 * Hex colours only here, as in the other emails: an email cannot read the app's tokens.
 */
import { TESTI_EMAIL_CLIENTE as T } from '@/lib/percorso/testi'
import { codiceLeggibile } from '@/lib/validation/registrazione-cliente'

const BORDEAUX = '#7A1F2B'
const TESTO = '#1C1C1E'
const TENUE = '#6B6B70'
const SFONDO = '#F4F2EE'

function escape(testo: string) {
  return testo.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

export type TipoEmailCodice = 'registrazione' | 'accesso'

export function emailCodiceCliente(d: {
  tipo: TipoEmailCodice
  nome: string
  codice: string
  /** https://…/brand/percorso-alpha-email.png: an image, not a link */
  urlLogo: string
}): { oggetto: string; html: string; testo: string } {
  const registrazione = d.tipo === 'registrazione'
  const oggetto = registrazione ? T.oggettoRegistrazione : T.oggettoAccesso
  const codice = codiceLeggibile(d.codice)
  const validita = registrazione ? T.validitaRegistrazione : T.validitaAccesso
  const nonTu = registrazione ? T.nonTuRegistrazione : T.nonTuAccesso

  const testo = [`${T.saluto(d.nome)} ${T.codice(codice)} ${validita}`, '', nonTu, '', T.firma].join('\n')

  const html = `<!doctype html>
<html lang="it">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<title>${escape(oggetto)}</title>
</head>
<body style="margin:0;padding:0;background:${SFONDO};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${SFONDO};">
  <tr><td align="center" style="padding:32px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:480px;background:#FFFFFF;border-radius:12px;">
      <tr><td align="center" style="padding:28px 24px 8px;">
        <img src="${escape(d.urlLogo)}" width="112" alt="Percorso Alpha" style="display:block;width:112px;height:auto;border:0;">
      </td></tr>
      <tr><td style="padding:16px 28px 0;font-family:Helvetica,Arial,sans-serif;font-size:16px;line-height:24px;color:${TESTO};">
        ${escape(T.saluto(d.nome))} ${escape(T.codiceIntro)}
      </td></tr>
      <tr><td align="center" style="padding:16px 28px;">
        <p style="margin:0;font-family:'Courier New',monospace;font-size:32px;line-height:40px;letter-spacing:6px;font-weight:bold;color:${BORDEAUX};">${escape(codice)}</p>
      </td></tr>
      <tr><td style="padding:0 28px 8px;font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:22px;color:${TESTO};">
        ${escape(validita)}
      </td></tr>
      <tr><td style="padding:8px 28px 28px;font-family:Helvetica,Arial,sans-serif;font-size:13px;line-height:20px;color:${TENUE};">
        ${escape(nonTu)}<br><br>${escape(T.firma)}
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>`

  return { oggetto, html, testo }
}
